package com.canteen.management.controller;import com.canteen.management.dto.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import com.canteen.management.dto.ChangePasswordRequest;import com.canteen.management.dto.ApiResponse;import com.canteen.management.service.StudentService;import com.canteen.management.service.EmailService;import com.canteen.management.service.OtpService;import com.canteen.management.repository.StudentRepository;import com.canteen.management.entity.Student;import java.util.HashMap;import java.util.Map;@RestController@RequestMapping("/student")public class StudentController {    @Autowired    private StudentService studentService;    @Autowired    private OtpService otpService;    @Autowired    private EmailService emailService;    @Autowired    private StudentRepository studentRepository;    @PostMapping("/register")    public StudentResponse registerStudent(@Valid @RequestBody StudentRequest studentRequest) {        return studentService.saveStudent(studentRequest);    }    @PutMapping("/profile")    public UpdateProfileResponse updateProfile(            @RequestBody UpdateProfileRequest request) {        return studentService.updateProfile(request);    }    @PostMapping("/login")    public LoginResponse login(@RequestBody LoginRequest loginRequest) {        return studentService.login(loginRequest);    }    @GetMapping("/{studentId}")    public StudentResponse getStudentByStudentId(@PathVariable String studentId) {        return studentService.getStudentByStudentId(studentId);    }    @PostMapping("/forgot-password")    public ApiResponse forgotPassword(            @RequestBody ForgotPasswordRequest request) {        Student student = studentRepository.findByEmail(request.getEmail());        if (student == null) {            return new ApiResponse("Email Not Registered");        }        String otp = otpService.generateOtp(request.getEmail());        emailService.sendOtp(request.getEmail(), otp);        return new ApiResponse("OTP Sent Successfully");    }    @PostMapping("/verify-otp")    public ApiResponse verifyOtp(            @RequestBody VerifyOtpRequest request) {        boolean valid = otpService.verifyOtp(                request.getEmail(),                request.getOtp()        );        if (valid) {            return new ApiResponse("OTP Verified");        }        return new ApiResponse("Invalid OTP");    }    @PostMapping("/reset-password")    public ApiResponse resetPassword(            @RequestBody ResetPasswordRequest request) {        Student student = studentRepository.findByEmail(request.getEmail());        if (student == null) {            return new ApiResponse("User Not Found");        }        student.setPassword(request.getNewPassword());        studentRepository.save(student);        return new ApiResponse("Password Reset Successfully");    }    @PostMapping("/change-password")    public ApiResponse changePassword(            @RequestBody ChangePasswordRequest request) {        return studentService.changePassword(request);    }    @PostMapping("/save-token")    public ApiResponse saveToken(            @RequestBody SaveFcmTokenRequest request){        return studentService.saveFcmToken(request);    }    @PostMapping("/google-login")    public LoginResponse googleLogin(            @RequestBody GoogleLoginRequest request) {        return studentService.googleLogin(request);    }    @GetMapping("/branch/{branchId}")    public java.util.List<Student> getStudentsByBranch(@PathVariable Long branchId) {        return studentRepository.findByBranchIdAndRole(branchId, "STUDENT");    }}